#undef main
static unsigned cases,errors,boundaries,fault_cases,vm_faults;
#define CHECK(v) do{if(!(v)){fprintf(stderr,"FAIL Lua TLS workspace cases=%u line=%d: %s\n",cases,__LINE__,#v);exit(1);}}while(0)
static char diagnostic[2048];
static int log_message(const char *format,va_list args){size_t n=strlen(diagnostic);CHECK(n<sizeof(diagnostic));return vsnprintf(diagnostic+n,sizeof(diagnostic)-n,format,args);}
int DLOG(const char *format,...){va_list args;va_start(args,format);int n=log_message(format,args);va_end(args);return n;}
int DLOG_ERR(const char *format,...){va_list args;va_start(args,format);int n=log_message(format,args);va_end(args);return n;}
#include "tls_mod_windows.inc"
