static void put16(uint8_t *data,size_t value){data[0]=value>>8;data[1]=value;}
static void put24(uint8_t *data,size_t value){data[0]=value>>16;data[1]=value>>8;data[2]=value;}
static size_t hello(uint8_t *data,const char *host,unsigned sid,unsigned padding){memset(data,0,2048);data[0]=22;data[1]=3;data[2]=1;data[5]=1;data[9]=3;data[10]=3;data[43]=sid;for(unsigned i=0;i<sid;++i)data[44+i]=33+i;size_t n=44+sid;data[n++]=0;data[n++]=2;data[n++]=19;data[n++]=1;data[n++]=1;data[n++]=0;size_t ext=n;n+=2;size_t hn=strlen(host);data[n++]=0;data[n++]=0;put16(data+n,hn+5);n+=2;put16(data+n,hn+3);n+=2;data[n++]=0;put16(data+n,hn);n+=2;memcpy(data+n,host,hn);n+=hn;if(padding){put16(data+n,21);put16(data+n+2,5);n+=4;memset(data+n,0,5);n+=5;if(padding==2){put16(data+n,0xffee);put16(data+n+2,0);n+=4;}}put16(data+ext,n-ext-2);put16(data+3,n-5);put24(data+6,n-9);return n;}
struct allocator{bool armed;unsigned limit,calls,rejected,live;};static struct allocator *fault_allocator;
static void *allocate(void *context,void *pointer,size_t previous,size_t next){struct allocator *a=context;if(!next){if(pointer){CHECK(a->live);--a->live;}free(pointer);return NULL;}if(a->armed && next>previous && a->calls++>=a->limit){++a->rejected;return NULL;}bool fresh=!pointer;void *result=realloc(pointer,next);if(result && fresh)++a->live;return result;}
struct sample{int status,type;size_t length;uint8_t data[4096];long random_after;char log[2048],message[512];};
static lua_State *new_vm(struct allocator *a){lua_State *L=a?lua_newstate(allocate,a):luaL_newstate();CHECK(L);luaJIT_setmode(L,0,LUAJIT_MODE_ENGINE|LUAJIT_MODE_OFF);return L;}
static void execute(lua_State *L,bool rust,const uint8_t *data,size_t length,const char *options,size_t options_length,const uint8_t *payload,size_t payload_length,unsigned argc,unsigned bad,struct sample *s){lua_settop(L,0);lua_pushlstring(L,(const char *)data,length);int ref=luaL_ref(L,LUA_REGISTRYINDEX);lua_pushcfunction(L,rust?luacall_tls_mod:reference_lua_tls_mod);for(unsigned i=1;i<=argc;++i){if(i==bad){lua_pushinteger(L,42);continue;}if(i==1)lua_rawgeti(L,LUA_REGISTRYINDEX,ref);else if(i==2)lua_pushlstring(L,options,options_length);else if(i==3 && payload)lua_pushlstring(L,(const char *)payload,payload_length);else lua_pushnil(L);}srandom(1234);diagnostic[0]=0;
    if(fault_allocator){fault_allocator->armed=true;fault_allocator->calls=fault_allocator->rejected=0;}s->status=lua_pcall(L,argc,1,0);if(fault_allocator)fault_allocator->armed=false;s->random_after=random();snprintf(s->log,sizeof(s->log),"%s",diagnostic);CHECK(lua_gettop(L)==1);if(s->status){const char *msg=lua_tostring(L,-1);snprintf(s->message,sizeof(s->message),"%s",msg?msg:"");}else{s->type=lua_type(L,-1);if(s->type==LUA_TSTRING){const char *value=lua_tolstring(L,-1,&s->length);CHECK(s->length<=sizeof(s->data));memcpy(s->data,value,s->length);}else CHECK(s->type==LUA_TNIL);}
    lua_rawgeti(L,LUA_REGISTRYINDEX,ref);size_t actual;const char *source=lua_tolstring(L,-1,&actual);CHECK(actual==length && !memcmp(source,data,length));luaL_unref(L,LUA_REGISTRYINDEX,ref);lua_settop(L,0);
}
static void compare(lua_State *L,const uint8_t *data,size_t length,const char *options,size_t options_length,const uint8_t *payload,size_t payload_length,unsigned argc,unsigned bad){struct sample a={0},b={0};execute(L,false,data,length,options,options_length,payload,payload_length,argc,bad,&a);execute(L,true,data,length,options,options_length,payload,payload_length,argc,bad,&b);if(memcmp(&a,&b,sizeof(a))){fprintf(stderr,"DETAIL length=%zu modlist=%s payload=%zu argc=%u bad=%u olderr=%d newerr=%d oldtype=%d newtype=%d oldlen=%zu newlen=%zu oldrandom=%ld newrandom=%ld\noldmsg=%s\nnewmsg=%s\noldlog=%s\nnewlog=%s\n",length,options,payload_length,argc,bad,a.status,b.status,a.type,b.type,a.length,b.length,a.random_after,b.random_after,a.message,b.message,a.log,b.log);CHECK(false);}++cases;if(a.status)++errors;}
static void boundary_checks(void){_Alignas(8)uint8_t bytes[512];memset(bytes,0xa5,sizeof(bytes));zapret_lua_tls_workspace *w=(void *)bytes;CHECK(zapret_lua_tls_prepare(NULL,0,w)==4);++boundaries;CHECK(zapret_lua_tls_prepare("rnd",0,NULL)==4);++boundaries;CHECK(zapret_lua_tls_prepare("rnd",0,(void *)(bytes+1))==4);++boundaries;CHECK(zapret_lua_tls_prepare("bad",SIZE_MAX,w)==2 && bytes[0]==0xa5);++boundaries;CHECK(zapret_lua_tls_prepare("rnd",SIZE_MAX,w)==3 && bytes[0]==0xa5);++boundaries;CHECK(zapret_lua_tls_prepare("none",SIZE_MAX,w)==3);++boundaries;CHECK(zapret_lua_tls_prepare("rnd",3,w)==1);size_t written=99;CHECK(!zapret_lua_tls_apply(w,NULL,NULL,0,bytes+300,&written,NULL) && written==99);++boundaries;w->capacity=1;CHECK(!zapret_lua_tls_apply(w,(const uint8_t *)"abc",NULL,0,bytes+300,&written,NULL) && written==99);++boundaries;
    uint8_t *buffer=VirtualAlloc(NULL,8192,MEM_RESERVE|MEM_COMMIT,PAGE_READWRITE);CHECK(buffer);DWORD old;CHECK(VirtualProtect(buffer+4096,4096,PAGE_NOACCESS,&old));zapret_lua_tls_workspace *end=(void *)(buffer+4096-sizeof(*end));CHECK(zapret_lua_tls_prepare("sni=x.y",3,end)==1);CHECK(VirtualProtect(buffer,4096,PAGE_READONLY,&old));uint8_t output[263];memset(output,0xa5,sizeof(output));CHECK(!zapret_lua_tls_apply(end,(const uint8_t *)"abc",NULL,0,output,&written,NULL) && written==99 && !memcmp(output,"abc",3));++boundaries;CHECK(VirtualFree(buffer,0,MEM_RELEASE));}
static void faults(const uint8_t *data,size_t length,const uint8_t *payload,size_t payload_length){const char *lists[]={"none","rnd","sni=longer.example.org","dupsid,padencap","rnd,rndsni,dupsid,padencap"};for(unsigned list=0;list<5;++list){struct sample baseline={0};lua_State *initial=new_vm(NULL);execute(initial,false,data,length,lists[list],strlen(lists[list]),payload,payload_length,3,0,&baseline);CHECK(!baseline.status);lua_close(initial);srandom(1234);long untouched=random();for(unsigned side=0;side<2;++side)for(unsigned limit=0;limit<24;++limit){struct allocator a={.limit=limit};lua_State *L=new_vm(&a);struct sample sample={0};fault_allocator=&a;execute(L,side!=0,data,length,lists[list],strlen(lists[list]),payload,payload_length,3,0,&sample);fault_allocator=NULL;if(sample.status){CHECK(sample.status==LUA_ERRMEM && a.rejected && (sample.random_after==untouched || sample.random_after==baseline.random_after));++vm_faults;}else CHECK(!a.rejected && !memcmp(&sample,&baseline,sizeof(sample)));lua_close(L);CHECK(!a.live);++fault_cases;}}CHECK(vm_faults>0);}
int main(void){uint8_t input[2048],payload[2048];size_t payload_length=hello(payload,"real.example.net",32,1);const char *lists[]={"","none","rnd","rndsni","sni=a.b","dupsid","padencap","rnd,rndsni","rnd,sni=longer.hostname.example.org,dupsid,padencap","none,rnd,none","bad","sni=","rnd,,dupsid","none\0bad","sni=\xd0\xbf\xd1\x80\xd0\xb8\xd0\xbc\xd0\xb5\xd1\x80.\xd1\x80\xd1\x84","dupsid,padencap"};lua_State *L=new_vm(NULL);for(unsigned variant=0;variant<9;++variant){size_t length=hello(input,variant%2?"www.example.com":"a.b",variant/3==0?0:variant/3==1?32:255,variant%3);for(unsigned list=0;list<16;++list)for(unsigned p=0;p<4;++p){const uint8_t *body=p?payload:NULL;size_t body_length=p==1?0:p==2?40:payload_length;for(size_t cut=0;cut<=length;++cut)compare(L,input,cut,lists[list],list==13?8:strlen(lists[list]),body,body_length,3,0);}}
    size_t length=hello(input,"www.example.com",32,1);for(unsigned argc=0;argc<5;++argc)for(unsigned bad=0;bad<4;++bad)for(unsigned list=0;list<16;++list)compare(L,input,length,lists[list],strlen(lists[list]),payload,payload_length,argc,bad);lua_close(L);boundary_checks();faults(input,length,payload,payload_length);printf("PASS lua_tls_workspace cases=%u vm_errors=%u boundaries=%u fault_cases=%u vm_allocation_faults=%u real_luajit=1 exact_errors=1 exact_diagnostics=1 exact_prng_state=1 immutable_input=1 bounded_workspace=1 c_only_unwind=1 vm_allocations_released=1\n",cases,errors,boundaries,fault_cases,vm_faults);return 0;}
